import sys
from src.parser import parse_enabled


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]

    if len(argv) != 1:
        print("usage: parser-cli <value>", file=sys.stderr)
        return 2

    value = argv[0]
    result = parse_enabled(value)

    if result:
        print("true")
        return 0
    else:
        print("false")
        return 1


if __name__ == "__main__":
    sys.exit(main())
